/**
 * Application settings persistence and change notification.
 *
 * Follows the same subscribe-notify pattern as ThemeManager but generalizes
 * to all user preferences. Stores a single JSON blob in localStorage under
 * the key 'cypcb-settings'. Missing or corrupt data falls back to defaults.
 *
 * Debug surface: `window.__settings` exposes the current snapshot for E2E.
 */

import type { DisplayUnit } from './units';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface LayerColors {
  topCopper: string;
  bottomCopper: string;
  silkscreen: string;
  via: string;
  drill: string;
}

export interface AppSettings {
  /** Theme preference: light, dark, or auto (follow OS) */
  theme: 'light' | 'dark' | 'auto';
  /** Display unit for dimensions */
  units: DisplayUnit;
  /** Visual grid spacing in nanometers */
  gridVisualSpacing: number;
  /** Snap grid spacing in nanometers */
  gridSnapSpacing: number;
  /** Whether the grid overlay is visible */
  gridVisible: boolean;
  /** Whether the ratsnest overlay is visible */
  ratsnestVisible: boolean;
  /** Whether net labels are visible */
  netLabelsVisible: boolean;
  /** Layer color overrides */
  layerColors: LayerColors;
}

export type SettingsKey = keyof AppSettings;
export type SettingsListener = (settings: AppSettings) => void;

// ---------------------------------------------------------------------------
// Defaults
// ---------------------------------------------------------------------------

/**
 * Default settings matching current hardcoded behavior:
 * - mm units
 * - 1mm visual grid (1_000_000 nm)
 * - 50mil snap grid (1_270_000 nm)
 * - all overlays visible
 * - standard RenderConfig layer colors
 */
export const DEFAULT_SETTINGS: Readonly<AppSettings> = {
  theme: 'auto',
  units: 'mm',
  gridVisualSpacing: 1_000_000,
  gridSnapSpacing: 1_270_000,
  gridVisible: true,
  ratsnestVisible: true,
  netLabelsVisible: true,
  layerColors: {
    topCopper: '#C83434',
    bottomCopper: '#3434C8',
    silkscreen: '#C8C800',
    via: '#808080',
    drill: '#FFFFFF',
  },
};

// ---------------------------------------------------------------------------
// Storage key
// ---------------------------------------------------------------------------

const STORAGE_KEY = 'cypcb-settings';

// ---------------------------------------------------------------------------
// Implementation
// ---------------------------------------------------------------------------

function loadFromStorage(): AppSettings {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { ...DEFAULT_SETTINGS, layerColors: { ...DEFAULT_SETTINGS.layerColors } };

    const parsed = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null) {
      console.warn('[settings] Invalid localStorage data, falling back to defaults');
      return { ...DEFAULT_SETTINGS, layerColors: { ...DEFAULT_SETTINGS.layerColors } };
    }

    // Merge parsed values over defaults so missing keys get filled in
    return {
      ...DEFAULT_SETTINGS,
      ...parsed,
      layerColors: {
        ...DEFAULT_SETTINGS.layerColors,
        ...(parsed.layerColors ?? {}),
      },
    };
  } catch (e) {
    console.warn('[settings] Failed to parse localStorage data, falling back to defaults', e);
    return { ...DEFAULT_SETTINGS, layerColors: { ...DEFAULT_SETTINGS.layerColors } };
  }
}

function saveToStorage(settings: AppSettings): void {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(settings));
  } catch {
    // Storage full or unavailable — silently degrade
  }
}

// ---------------------------------------------------------------------------
// Exported API
// ---------------------------------------------------------------------------

let current: AppSettings = loadFromStorage();
const listeners: Set<SettingsListener> = new Set();

function notifyListeners(): void {
  const snapshot = getSettings();
  listeners.forEach((fn) => fn(snapshot));
}

function exposeDebugSurface(): void {
  if (typeof window !== 'undefined') {
    (window as any).__settings = getSettings();
  }
}

/**
 * Get the full current settings snapshot (deep copy).
 */
export function getSettings(): AppSettings {
  return {
    ...current,
    layerColors: { ...current.layerColors },
  };
}

/**
 * Get a single preference value.
 */
export function getPreference<K extends SettingsKey>(key: K): AppSettings[K] {
  const val = current[key];
  // Deep-copy layerColors to prevent external mutation
  if (key === 'layerColors' && typeof val === 'object') {
    return { ...(val as any) } as AppSettings[K];
  }
  return val;
}

/**
 * Set a single preference value, persist to localStorage, and notify listeners.
 */
export function setPreference<K extends SettingsKey>(key: K, value: AppSettings[K]): void {
  // Deep-copy layerColors on write
  if (key === 'layerColors' && typeof value === 'object') {
    current[key] = { ...(value as any) } as AppSettings[K];
  } else {
    current[key] = value;
  }
  saveToStorage(current);
  exposeDebugSurface();
  notifyListeners();
}

/**
 * Subscribe to any settings change.
 * @returns Unsubscribe function.
 */
export function subscribe(listener: SettingsListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/**
 * Reset all settings to defaults (useful for testing).
 */
export function resetSettings(): void {
  current = { ...DEFAULT_SETTINGS, layerColors: { ...DEFAULT_SETTINGS.layerColors } };
  saveToStorage(current);
  exposeDebugSurface();
  notifyListeners();
}

// ---------------------------------------------------------------------------
// Initialize debug surface
// ---------------------------------------------------------------------------

exposeDebugSurface();

/**
 * Unit formatting and parsing utilities.
 *
 * Internal representation is always nanometers. These functions convert
 * between nanometers and human-readable dimension strings in mm, mil, or µm.
 */

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export type DisplayUnit = 'mm' | 'mil' | 'µm';

// ---------------------------------------------------------------------------
// Conversion constants (nanometers per unit)
// ---------------------------------------------------------------------------

/** 1 mm = 1,000,000 nm */
export const NM_PER_MM = 1_000_000;

/** 1 mil (thousandth of an inch) = 25,400 nm */
export const NM_PER_MIL = 25_400;

/** 1 µm = 1,000 nm */
export const NM_PER_UM = 1_000;

// ---------------------------------------------------------------------------
// Formatting
// ---------------------------------------------------------------------------

/**
 * Format a dimension from nanometers to a human-readable string.
 *
 * Examples:
 *   formatDimension(2_540_000, 'mm')  → "2.54mm"
 *   formatDimension(2_540_000, 'mil') → "100.00mil"
 *   formatDimension(2_540_000, 'µm')  → "2540µm"
 */
export function formatDimension(nm: number, unit: DisplayUnit): string {
  switch (unit) {
    case 'mm': {
      const val = nm / NM_PER_MM;
      return `${stripTrailingZeros(val.toFixed(4))}mm`;
    }
    case 'mil': {
      const val = nm / NM_PER_MIL;
      return `${stripTrailingZeros(val.toFixed(2))}mil`;
    }
    case 'µm': {
      const val = nm / NM_PER_UM;
      return `${stripTrailingZeros(val.toFixed(1))}µm`;
    }
  }
}

/**
 * Remove unnecessary trailing zeros from a decimal string while keeping
 * at least one decimal place for mm/mil readability.
 *
 *   "2.5400" → "2.54"
 *   "100.00" → "100.00"  (keeps 2 decimal places minimum for mil)
 *   "3.0"    → "3.0"
 */
function stripTrailingZeros(s: string): string {
  if (!s.includes('.')) return s;
  // Remove trailing zeros but keep at least one digit after the dot
  let end = s.length;
  while (end > 0 && s[end - 1] === '0') end--;
  if (s[end - 1] === '.') end++; // keep "3.0" not "3."
  return s.slice(0, end);
}

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

/**
 * Unit suffix patterns for parsing. Order matters — check longer suffixes first.
 * Handles: mm, mil, µm, um (alias for µm)
 */
const UNIT_PATTERNS: [RegExp, number][] = [
  [/mil$/i, NM_PER_MIL],
  [/mm$/i, NM_PER_MM],
  [/[µu]m$/i, NM_PER_UM],
];

/**
 * Parse a user-entered dimension string to nanometers.
 *
 * Accepts formats like: "2.54mm", "100mil", "2540µm", "2540um"
 * Whitespace between number and unit is tolerated.
 * Returns null for invalid input.
 */
export function parseUserDimension(input: string): number | null {
  const trimmed = input.trim();
  if (!trimmed) return null;

  for (const [pattern, nmPerUnit] of UNIT_PATTERNS) {
    // Find the unit suffix
    const match = trimmed.match(pattern);
    if (match) {
      const numStr = trimmed.slice(0, match.index!).trim();
      const num = Number(numStr);
      if (!isFinite(num) || numStr === '') return null;
      return Math.round(num * nmPerUnit);
    }
  }

  return null;
}

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';

/**
 * Settings module tests.
 *
 * The settings module runs side-effects at import time (reads localStorage,
 * sets window.__settings). We need to set up the mock environment BEFORE
 * importing, then re-import for each test to get clean state.
 */

// ---------------------------------------------------------------------------
// Helpers: mock localStorage + window for node environment
// ---------------------------------------------------------------------------

let storage: Record<string, string> = {};

const mockLocalStorage = {
  getItem: vi.fn((key: string) => storage[key] ?? null),
  setItem: vi.fn((key: string, value: string) => { storage[key] = value; }),
  removeItem: vi.fn((key: string) => { delete storage[key]; }),
  clear: vi.fn(() => { storage = {}; }),
};

function setupGlobals() {
  (globalThis as any).localStorage = mockLocalStorage;
  if (typeof globalThis.window === 'undefined') {
    (globalThis as any).window = {};
  }
}

function teardownGlobals() {
  delete (globalThis as any).localStorage;
  delete (globalThis as any).window;
}

// We need a fresh module per test since the module has top-level state.
async function importSettings() {
  // Bust the module cache so we get fresh state on each import
  const mod = await import('../settings');
  return mod;
}

beforeEach(() => {
  storage = {};
  vi.clearAllMocks();
  setupGlobals();
  vi.resetModules();
});

afterEach(() => {
  teardownGlobals();
});

describe('settings', () => {
  it('returns DEFAULT_SETTINGS when localStorage is empty', async () => {
    const { getSettings, DEFAULT_SETTINGS } = await importSettings();
    expect(getSettings()).toEqual(DEFAULT_SETTINGS);
  });

  it('get/set round-trip for a simple preference', async () => {
    const { getPreference, setPreference } = await importSettings();
    expect(getPreference('units')).toBe('mm');

    setPreference('units', 'mil');
    expect(getPreference('units')).toBe('mil');
  });

  it('persists changes to localStorage', async () => {
    const { setPreference } = await importSettings();

    setPreference('gridVisible', false);

    const stored = JSON.parse(storage['cypcb-settings']);
    expect(stored.gridVisible).toBe(false);
  });

  it('subscribe notifies on change', async () => {
    const { subscribe, setPreference } = await importSettings();

    const listener = vi.fn();
    subscribe(listener);

    setPreference('units', 'mil');

    expect(listener).toHaveBeenCalledTimes(1);
    expect(listener.mock.calls[0][0].units).toBe('mil');
  });

  it('supports multiple subscribers', async () => {
    const { subscribe, setPreference } = await importSettings();

    const listener1 = vi.fn();
    const listener2 = vi.fn();
    subscribe(listener1);
    subscribe(listener2);

    setPreference('gridVisible', false);

    expect(listener1).toHaveBeenCalledTimes(1);
    expect(listener2).toHaveBeenCalledTimes(1);
  });

  it('unsubscribe stops notifications', async () => {
    const { subscribe, setPreference } = await importSettings();

    const listener = vi.fn();
    const unsub = subscribe(listener);

    setPreference('units', 'mil');
    expect(listener).toHaveBeenCalledTimes(1);

    unsub();
    setPreference('units', 'µm');
    // Should NOT have been called again
    expect(listener).toHaveBeenCalledTimes(1);
  });

  it('falls back to defaults when localStorage contains invalid JSON', async () => {
    storage['cypcb-settings'] = '{not valid json!!!';

    const { getSettings, DEFAULT_SETTINGS } = await importSettings();
    expect(getSettings()).toEqual(DEFAULT_SETTINGS);
  });

  it('merges partial settings with defaults', async () => {
    storage['cypcb-settings'] = JSON.stringify({ units: 'mil' });

    const { getSettings, DEFAULT_SETTINGS } = await importSettings();
    const settings = getSettings();

    // Overridden value
    expect(settings.units).toBe('mil');
    // Default values still present
    expect(settings.gridVisualSpacing).toBe(DEFAULT_SETTINGS.gridVisualSpacing);
    expect(settings.layerColors).toEqual(DEFAULT_SETTINGS.layerColors);
  });

  it('falls back to defaults when localStorage value is not an object', async () => {
    storage['cypcb-settings'] = JSON.stringify('just a string');

    const { getSettings, DEFAULT_SETTINGS } = await importSettings();
    expect(getSettings()).toEqual(DEFAULT_SETTINGS);
  });

  it('exposes window.__settings debug surface', async () => {
    await importSettings();
    expect((globalThis as any).window.__settings).toBeDefined();
    expect((globalThis as any).window.__settings.units).toBe('mm');
  });

  it('get/set round-trip for layerColors', async () => {
    const { getPreference, setPreference } = await importSettings();

    const newColors = {
      topCopper: '#FF0000',
      bottomCopper: '#00FF00',
      silkscreen: '#0000FF',
      via: '#AAAAAA',
      drill: '#000000',
    };
    setPreference('layerColors', newColors);
    expect(getPreference('layerColors')).toEqual(newColors);
  });

  it('resetSettings restores defaults and notifies', async () => {
    const { setPreference, resetSettings, getSettings, subscribe, DEFAULT_SETTINGS } = await importSettings();

    setPreference('units', 'mil');
    const listener = vi.fn();
    subscribe(listener);

    resetSettings();

    expect(getSettings()).toEqual(DEFAULT_SETTINGS);
    expect(listener).toHaveBeenCalledTimes(1);
  });
});

import { describe, it, expect } from 'vitest';
import {
  formatDimension,
  parseUserDimension,
  NM_PER_MM,
  NM_PER_MIL,
  NM_PER_UM,
} from '../units';

describe('formatDimension', () => {
  it('formats nanometers to mm', () => {
    expect(formatDimension(2_540_000, 'mm')).toBe('2.54mm');
    expect(formatDimension(1_000_000, 'mm')).toBe('1mm');
    expect(formatDimension(500_000, 'mm')).toBe('0.5mm');
  });

  it('formats nanometers to mil', () => {
    expect(formatDimension(2_540_000, 'mil')).toBe('100mil');
    expect(formatDimension(25_400, 'mil')).toBe('1mil');
    expect(formatDimension(254_000, 'mil')).toBe('10mil');
  });

  it('formats nanometers to µm', () => {
    expect(formatDimension(2_540_000, 'µm')).toBe('2540µm');
    expect(formatDimension(1_000, 'µm')).toBe('1µm');
    expect(formatDimension(500, 'µm')).toBe('0.5µm');
  });

  it('handles zero', () => {
    expect(formatDimension(0, 'mm')).toBe('0mm');
    expect(formatDimension(0, 'mil')).toBe('0mil');
    expect(formatDimension(0, 'µm')).toBe('0µm');
  });

  it('handles negative values', () => {
    expect(formatDimension(-1_000_000, 'mm')).toBe('-1mm');
    expect(formatDimension(-25_400, 'mil')).toBe('-1mil');
    expect(formatDimension(-1_000, 'µm')).toBe('-1µm');
  });

  it('handles very large values', () => {
    expect(formatDimension(100_000_000_000, 'mm')).toBe('100000mm');
    expect(formatDimension(100_000_000_000, 'mil')).toContain('mil');
  });
});

describe('parseUserDimension', () => {
  it('parses mm values to nanometers', () => {
    expect(parseUserDimension('2.54mm')).toBe(2_540_000);
    expect(parseUserDimension('1mm')).toBe(1_000_000);
    expect(parseUserDimension('0.5mm')).toBe(500_000);
  });

  it('parses mil values to nanometers', () => {
    expect(parseUserDimension('100mil')).toBe(2_540_000);
    expect(parseUserDimension('1mil')).toBe(25_400);
    expect(parseUserDimension('50mil')).toBe(1_270_000);
  });

  it('parses µm values to nanometers', () => {
