/**
 * Remove unnecessary trailing zeros from a decimal string while keeping
 * at least one decimal place for mm/mil readability.
 *
 *   "2.5400" → "2.54"
 *   "100.00" → "100.00"  (keeps 2 decimal places minimum for mil)
 *   "3.0"    → "3.0"
 */
function stripTrailingZeros(s: string): string {
  if (!s.includes('.')) return s;
  // Remove trailing zeros but keep at least one digit after the dot
  let end = s.length;
  while (end > 0 && s[end - 1] === '0') end--;
  if (s[end - 1] === '.') end++; // keep "3.0" not "3."
  return s.slice(0, end);
}

